                    {"role": "user", "content": user},
                ],
                "stream": False,
            },
            timeout=180.0,
        )
        response.raise_for_status()
    except httpx.HTTPError as exc:
        raise OllamaChatError(
            f"Ollama chat call failed (host={settings.ollama_host}): {exc}"
        ) from exc
    return response.json()["message"].get("content", "")


